// Nelson Mandelabrug, Arnhem — expliciete dekvlakken, kokerlofts en BGT-pijlers.
// Bronnen en schattingen: models/nelson-mandelabrug/README.md.
// Offline reproduceerbaar: geen netwerkverzoeken, geen AHN-hoogtelagen.
import Module from "manifold-3d";
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
const wasm = await Module(); wasm.setup();
const { Manifold, CrossSection, Mesh } = wasm;
const args = process.argv.slice(2);
const flag = (s, d) => { const i=args.indexOf(s); return i>=0 ? args[i+1] : d; };
const scale=Number(flag("--scale", "1000")), mmPerMetre=1000/scale;
const outDir=path.resolve(flag("--out", path.join(import.meta.dirname,"../models/nelson-mandelabrug")));
const WATER_NAP=8.25; // PDOK Rijnwater bij de nabijgelegen John Frostbrug; waterbemonstering op eigen brug.
const SLAB=1.35, ROAD_LAYER=.5, MINIMUM=.9;
const union = (ss) => Manifold.union(ss.filter(s=>!s.isEmpty()));
const ccw = (r) => r.reduce((a,p,i)=>a+p[0]*r[(i+1)%r.length][1]-p[1]*r[(i+1)%r.length][0],0)>0?r:[...r].reverse();
const section = (r) => new CrossSection([ccw(r)]);
const prism = (r,z,h) => Manifold.extrude(section(r),h).translate([0,0,z]);
const rect = (x0,y0,x1,y1) => [[x0,y0],[x1,y0],[x1,y1],[x0,y1]];
const box = (x0,y0,z0,x1,y1,z1) => prism(rect(x0,y0,x1,y1),z0,z1-z0);
const ORIGIN=[190231.098, 443540.899];
const AXIS=[0.5790130018829376, 0.8153183081781675];
