// AHN-DSM: medianen op de verkeersbanen, geen auto's of vangrails.
const MAIN_PROFILE=[[-114,25.10],[-100,25.20],[-75,25.60],[-50,25.90],[-25,26.05],[0,26.267],[25,26.424],[50,26.45],[75,26.228],[100,25.914],[125,25.53],[150,24.836],[175,24.048],[200,23.22],[225,22.655],[250,22.082],[275,21.495],[300,20.863],[325,20.311],[340,19.96]];
function mainNap(x) {
  const i=Math.max(0,Math.min(MAIN_PROFILE.length-2,MAIN_PROFILE.findIndex(p=>p[0]>x)-1));
  if(x>=340)return MAIN_PROFILE.at(-1)[1];
  const [a,b]=[MAIN_PROFILE[i],MAIN_PROFILE[i+1]];
  return a[1]+(b[1]-a[1])*Math.max(0,Math.min(1,(x-a[0])/(b[0]-a[0])));
}
// De noordelijke lus is een continu hellend dekvlak. AHN-punten op de lus:
// (240,50)=22.60; (240,100)=21.64; (240,150)=21.01;
// (240,200)=20.24; (190,210)=19.46; (230,240)=18.70; (225,265)=17.84 m NAP.
// De terugtak aan de binnenkant ligt iets lager dan de uitgaande baan.
function topNap(x,y) {
  const loop=23.45-.016*y+.012*(x-240)-.024*Math.max(0,y-215)
    -.7*Math.max(0,Math.min(1,(200-x)/20))*Math.max(0,Math.min(1,(210-y)/20));
  const f=Math.max(0,Math.min(1,(y-15)/35));
  return mainNap(x)*(1-f)+loop*f;
}
const top=(x,y)=>topNap(x,y)-WATER_NAP;
function loftX(stations, sectionAt) {
  const verts=[], tris=[], n=sectionAt(stations[0]).length;
  for(const x of stations)for(const [y,z] of sectionAt(x))verts.push(x,y,z);
  for(let i=0;i<stations.length-1;i++)for(let j=0;j<n;j++){
    const a=i*n+j,b=i*n+(j+1)%n,c=(i+1)*n+(j+1)%n,d=(i+1)*n+j;
    tris.push(a,b,c,a,c,d);
  }
  for(let j=1;j<n-1;j++){tris.push(0,j+1,j); const k=(stations.length-1)*n;tris.push(k,k+j,k+j+1);}
  return new Manifold(new Mesh({numProp:3,vertProperties:Float32Array.from(verts),triVerts:Uint32Array.from(tris)}));
}
